// --id is optional (was required): an explicit id is still honored
// as-is (e.g. a deliberately chosen or parent-lineage child id like
// "tsk-4vo-1"), but omitting it now reuses `submit`'s own generateId
// (src/intake/classify.mjs) to derive a collision-free "tsk-<hash>"
// id from --title, instead of forcing the caller to invent one by
// hand. This closes the gap that let `add` accept an arbitrarily
// long slugified-title id in the first place (docs/explanation/
// long-work-item-ids-max-length-guard.md) — generateId is now the
// path of least resistance, not a manually-typed guess.
const idFlag = optionalField(positional[0] ?? flags.id, 'add --id requires a non-empty value; omit --id entirely to auto-generate one from --title.');
if (flags.tier !== undefined) {
  throw new StoreError('validation', '--tier is retired; use --size (light|standard|heavy) or --rigor (low|standard|high|critical) instead.');
}
const id = idFlag ?? generateId(
  requireField(flags.title, 'add requires --title (used to derive the id when --id is omitted, and always required as the item\'s own title regardless)'),
  Object.keys(listWork(dir).work),
);
const work = {
  id,
  title: flags.title,
  kind: flags.kind,
  status: 'todo',
  deps: parseListFlag(flags.deps),
  risk: flags.risk,
  refs: parseListFlag(flags.refs),
  verify: flags.verify,
  description: requireField(flags.description, 'add requires --description (the item\'s own full-text intake description)'),
  learn: typeof flags.learn === 'string' ? flags.learn : undefined,
  size: optionalField(flags.size, 'add --size requires a size value (e.g. light/standard/heavy); omit --size entirely to use the default.'),
  rigor: optionalField(flags.rigor, 'add --rigor requires a rigor value (e.g. low/standard/high/critical); omit --rigor entirely to leave unset.'),
  // Per base-workflow-model D1-D4/S2: --domain is optional, same
  // omitted-leaves-undefined shape as --tier just above; omitting it

  const allowed = classificationVocabulary(domain, field);
  if (!allowed) return;
  if (!allowed.includes(work[field])) {
    throw new WorkValidationError(
      `work.${field} must be one of ${JSON.stringify(allowed)} for domain `
        + `"${work.domain ?? DEFAULT_DOMAIN}", got: ${JSON.stringify(work[field])}`,
    );
  }
}

/**
 * Validate the shape of a single work item: required fields, id format, and
 * that deps is an array of non-empty strings with no self-reference. Does
 * NOT check that deps point at ids that actually exist — that is
 * `validateDeps`, which needs the rest of the store to answer.
 *
 * `touchedFields` (optional, tsk-1ne D1/D2): a Set of top-level field names
 * to check — every other field is grandfathered, its already-stored value
 * left unvalidated regardless of whether it would pass today's rules.
 * Omitted (the default, `addWork`'s own call) means "check everything,"
 * byte-for-byte the original behavior. `editWork` (store.mjs) is the one
 * caller that ever passes a real Set: an edit patch can only ever contain
 * `EDITABLE_FIELDS` keys (id/status/workflowStep/domain are never among them, so
 * their checks below can never fire for an edit either way), and
 * re-rejecting an UNCHANGED field's pre-existing value on every edit — the
 * bug this parameter fixes — blocked 65/112 items from being edited at all
 * for legacy shape that predates a since-tightened rule (step enum,
 * id-length cap). This never widens what a NEW value in the patch must
 * satisfy — every check below still runs in full for any field actually
 * present in `touchedFields`.
 */
export function validateWorkShape(work, touchedFields) {
  if (!work || typeof work !== 'object' || Array.isArray(work)) {
    throw new WorkValidationError('work item must be an object.');
  }
  const touched = (field) => !touchedFields || touchedFields.has(field);

  if (touched('id')) {
    if (typeof work.id !== 'string' || !ID_PATTERN.test(work.id)) {
      throw new WorkValidationError(
        `work.id must be a stable kebab-case identifier (e.g. "add-login-form"), got: ${JSON.stringify(work.id)}`,
      );
    }
    if (work.id.length > MAX_ID_LENGTH) {
      throw new WorkValidationError(
        `work.id must be at most ${MAX_ID_LENGTH} characters (got ${work.id.length}): ${JSON.stringify(work.id)} — pick a short descriptive id, not a slugified title.`,
      );
    }
  }
  if (touched('title')) requireNonEmptyString(work, 'title');
  if (touched('kind')) {
    requireNonEmptyString(work, 'kind');
    requireDeclaredClassification(work, 'kind');
  }
  if (touched('status')) {
    requireNonEmptyString(work, 'status');

// Per D6/D7b: every NEW work.add event carries `tier` explicitly — the
// caller's own value, or work.mjs's declared DEFAULTS.tier when omitted —
// so the event log itself (not only replay.mjs's fold) states what tier
// was in effect at write time. `??` only fills in when `tier` is missing
// or nullish; an explicit (even invalid) value passes through unchanged
// so validateWork below still rejects it as validation.
//
// Per work-item-title-contract D2/D5, the title bound is applied HERE, on
// the same normalize step as tier and before validateWork — so the
// truncated title is what the appended event carries, and every caller
// reaching this door (submit and add in bin/fgos.mjs, decompose's children,
// the runner loop) obeys one rule without any of them repeating it.
const item = { ...work, size: work?.size ?? DEFAULTS.size, title: truncateTitle(work?.title) };
validateWork(item, Object.keys(before.work));
// domainFields fieldSchema (decision record 0027, D6): a separate,
// narrower check than validateWork's own domainFields shape rule above
// (work.mjs) — validates ONLY the namespace matching item's own domain

}
if (touched('risk')) {
  requireNonEmptyString(work, 'risk');
  requireDeclaredClassification(work, 'risk');
}
if (touched('refs')) requireArray(work, 'refs');
if (touched('verify')) requireNonEmptyString(work, 'verify');
